        /// <summary>
        ///   <para>
        ///     Resets the three sleep test spheres to the given points (the centre of mass, and two points along the
        ///     body), restarting the sleep timer.
        ///   </para>
        /// </summary>
        public unsafe void ResetSleepTestSpheres(ReadOnlySpan<float3> points)
        {
            fixed (float3* points_fixed = points)
            {
                if (points.Length != 3)
                    throw new ArgumentException(
                        "Expected exactly 3 points, one per sleep test sphere.",
                        nameof(points)
                    );
                Jolt.PInvoke.MotionProperties_ResetSleepTestSpheres(this, points_fixed, (nuint)points.Length);
            }
        }

